-- ---------------------------------------------------------------- (v2) visual recorder (server) / replay (client)
IT_BUF = {}
local function rec(name) return function(...) IT_BUF[#IT_BUF + 1] = { name, ... } end end
IT_ParticleReset = rec("ParticleReset")
IT_ParticleType = rec("ParticleType")
IT_ParticleTile = rec("ParticleTile")
IT_ParticleColor = rec("ParticleColor")
IT_ParticleRadius = rec("ParticleRadius")
IT_ParticleAlpha = rec("ParticleAlpha")
IT_ParticleGravity = rec("ParticleGravity")
IT_ParticleDrag = rec("ParticleDrag")
IT_ParticleEmissive = rec("ParticleEmissive")
IT_ParticleRotation = rec("ParticleRotation")
IT_ParticleStretch = rec("ParticleStretch")
IT_ParticleSticky = rec("ParticleSticky")
IT_ParticleCollide = rec("ParticleCollide")
IT_ParticleFlags = rec("ParticleFlags")
IT_SpawnParticle = rec("SpawnParticle")
IT_PointLight = rec("PointLight")
IT_PlaySound = rec("PlaySound")
IT_PlayLoop = rec("PlayLoop")
IT_ShakeCamera = rec("ShakeCamera")

-- effect functions: real on a client (IT_CLIENT), one recorded event on the server
function ITC_trailsAdd(...) if IT_CLIENT then return ITR_trailsAdd(...) end IT_BUF[#IT_BUF + 1] = { "@trailsAdd", ... } end
function ITC_trailsUpdate(...) if IT_CLIENT then return ITR_trailsUpdate(...) end IT_BUF[#IT_BUF + 1] = { "@trailsUpdate", ... } end
function ITC_smokeUpdate(...) if IT_CLIENT then return ITR_smokeUpdate(...) end IT_BUF[#IT_BUF + 1] = { "@smokeUpdate", ... } end
function ITC_fireUpdate(...) if IT_CLIENT then return ITR_fireUpdate(...) end IT_BUF[#IT_BUF + 1] = { "@fireUpdate", ... } end
function ITC_flashTick(...) if IT_CLIENT then return ITR_flashTick(...) end IT_BUF[#IT_BUF + 1] = { "@flashTick", ... } end
function ITC_lightTick(...) if IT_CLIENT then return ITR_lightTick(...) end IT_BUF[#IT_BUF + 1] = { "@lightTick", ... } end
function ITC_explosionSparks(...) if IT_CLIENT then return ITR_explosionSparks(...) end IT_BUF[#IT_BUF + 1] = { "@explosionSparks", ... } end
function ITC_explosionDebris(...) if IT_CLIENT then return ITR_explosionDebris(...) end IT_BUF[#IT_BUF + 1] = { "@explosionDebris", ... } end
function ITC_explosionSmall(...) if IT_CLIENT then return ITR_explosionSmall(...) end IT_BUF[#IT_BUF + 1] = { "@explosionSmall", ... } end
function ITC_explosionMedium(...) if IT_CLIENT then return ITR_explosionMedium(...) end IT_BUF[#IT_BUF + 1] = { "@explosionMedium", ... } end
