function server.tick(dt)
	if IsHandleValid(tank.id)then
		local status,retVal = pcall(tick_behaviors)
		if(not status) then
			DebugWatch("[ERROR] ",retVal)
		end
	end
	IT_Flush() -- (v2) this tick's visuals to every client; v1 removed the script once the tank was gone
end
function tick_behaviors( )
	if unexpected_condition then error() end

	if(not tank.dead) then
		if(DEBUG) then 
			DebugWatch("cook_off_value: ",cook_off_value)
			DebugWatch("cook_off_pulse: ",cook_off_pulse)

			DebugWatch("burn_off_value: ",burn_off_value)
		end

		if(tank.engines) then 
			check_engine_state()
		end
		if(tank.fuel_tanks and #tank.fuel_tanks>0) then 
			check_fuel_tank_state()
		end
		
		check_generic_survival_conditions()
	elseif(tank.burning_off and not tank.burned_off) then 
		burn_off()
		simulate_engine_disabled()
	else
		simulate_engine_disabled()
	end

end

function check_generic_survival_conditions()
	-- if(GetVehicleHealth(tank.id) <0.9) then 
	-- 	DebugWatch("vehilce health",GetVehicleHealth(tank.id))
	-- end
	if(not tank.cooking_off) then 
		-- kill tank on low health 
		if(GetVehicleHealth(tank.id) <min_tank_health) then 
			kill_tank(normal_kill_intensity)
		end
		if(tank.ammo_racks and #tank.ammo_racks>0) then 
			check_ammo_stability()
		end		
	else
		cook_off()
		-- DebugWatch("cooking off",cook_off_value)
	end
end


function kill_tank(max_intensity)
	min_intensity = 5
	max_intensity = max_intensity or 100
	tank.cooking_off = true
	break_all_breakable_joints()
	cook_off_intensity = math.random(min_intensity,max_intensity)/10
	if(cook_off_intensity<=2 and min_cook_off<4) then 
		min_cook_off = 4
	end
	SetValue("cook_off_value", 1, "easein", math.random(min_cook_off,max_cook_off))

	-- if(not IsHandleValid(tank.cook_off_loc)) then 
		local com = GetBodyCenterOfMass(GetVehicleBody(tank.id))
		-- DebugWatch("com",com)
	tank.cook_off_origin = Transform(com) -- (v2) was the bare vector, used as a transform below
		
	-- end

end


function check_engine_state()
	-- if(#tank.engines>0) then 
	-- 	DebugWatch("engne_state",tank.engine_okay)
	-- end
	for i = 1,#tank.engines do 
		if(not tank.engine_states[i] and IsShapeBroken(tank.engines[i])) then 
			tank.engine_okay = false
			ITC_explosionSmall(GetShapeWorldTransform(tank.engines[i]))
			tank.engine_states[i] = true
			tank.damaged_engines = tank.damaged_engines +1
		end
	end

	if(not tank.engine_okay) then 

		if(math.random()>0.8) then 
			for i =1,#tank.engines do 
				if(tank.engine_states[i]) then
					local engine_pos = GetShapeWorldTransform(tank.engines[i]) 
					ITC_engine_sparks(engine_pos,math.random(2,15),math.random(2,5))
					local hit, hitp,hitn,hitshape = QueryClosestPoint(engine_pos.pos,0.6)
					if(hit) then
							SpawnFire(hitp)
							-- hitLocations[i] = hitshape
					else
							SpawnFire(engine_pos.pos)
					end
				end
			end
		end
		simulate_engine_disabled()--DriveVehicle(tank.id,0,0,true)
	end
end


function simulate_engine_disabled()
	DriveVehicle(tank.id,0,0,true)
	if(IsHandleValid(base_vehicle)) then 
		DriveVehicle(tank.base_vehicle,0,0,true)
		
	end	
end

function ITR_engine_sparks(engine_pos,count, vel)
	for i=1, count do
		local v = VecAdd(Vec(0, vel, 0 ), rndVec(rnd(vel*0.5, vel*1.5)))
		local life = rnd(0, 1)
		life = life*life * 5
		IT_ParticleReset()
		IT_ParticleEmissive(5, 0, "easeout")
		IT_ParticleGravity(-10)
		IT_ParticleRadius(0.03, 0.0, "easein")
		IT_ParticleCollide(1, 1, "constant", 0.05)
		IT_ParticleColor(1, 0.4, 0.3)
		IT_ParticleTile(3)
		IT_SpawnParticle(engine_pos.pos, v, life)
	end
end



function check_fuel_tank_state()
	for i = 1,#tank.fuel_tanks do 
		if(not tank.fuel_tanks_states[i] and IsShapeBroken(tank.fuel_tanks[i])) then 
			tank.fuel_tanks_okay = false
			ITC_explosionSmall(GetShapeWorldTransform(tank.fuel_tanks[i]))
			tank.fuel_tanks_states[i] = true
			tank.damaged_fuel_tanks = tank.damaged_fuel_tanks +1
		end
	end

	if(not tank.fuel_tanks_okay) then 

			for i =1,#tank.fuel_tanks do 
				
			if(tank.fuel_tanks_states[i] and tank.fuel_tanks_volume[i] > 0 ) then
				tank.fuel_tanks_volume[i] = tank.fuel_tanks_volume[i] - (tank.fuel_leak_rate*GetTimeStep())
				-- DebugWatch("Fuel tank "..i.." volume",tank.fuel_tanks_volume[i])	
				if(math.random()>0.6) then 
					local fuel_tank_pos = GetShapeWorldTransform(tank.fuel_tanks[i]) 
					ITC_animated_fuel_leak(fuel_tank_pos ,math.random(2,15),math.random(2,10)/2)
					if(math.random()>0.8) then 
						spawn_leaking_fuel(fuel_tank_pos.pos)
						local hit, hitp,hitn,hitshape = QueryClosestPoint(fuel_tank_pos.pos,0.6)
						if(hit) then
								SpawnFire(hitp)
								Paint(hitp, 0.2, "explosion")
								-- hitLocations[i] = hitshape
						else
								SpawnFire(fuel_tank_pos.pos)
								Paint(fuel_tank_pos.pos, 0.2, "explosion")
						end						
					end

				end
			end
		end
	end
end


function ITR_animated_fuel_leak(engine_pos,count, vel)
	for i=1, count do
		local v = VecAdd(Vec(0, vel, 0 ), rndVec(rnd(vel*0.5, vel*1.5)))
		local life = rnd(0, 1)
		life = life*life * 5
		IT_ParticleReset()
		IT_ParticleEmissive(1, 0, "easeout")
		IT_ParticleGravity(-10)
		IT_ParticleSticky(0.1)
		IT_ParticleRadius(0.03, 0.0, "easein")
		IT_ParticleCollide(1, 1, "constant", 0.05)
		IT_ParticleColor(0.01, 0.01, 0.05)
		IT_ParticleTile(4)
		IT_SpawnParticle(engine_pos.pos, v, life)
	end
end

function check_ammo_stability()
	if(not tank.cooking_off and #tank.ammo_racks>0) then 
		local stable_ammo = #tank.ammo_racks 
		for i=1,#tank.ammo_racks do
			local ammo_rack = tank.ammo_racks[i]
			if(tank.cooking_off) then 
				SpawnFire(GetShapeWorldTransform(ammo_rack).pos)
			elseif(not tank.ammo_rack_state[i]) then 
				stable_ammo = stable_ammo-1
			end
			local hit, pos =QueryClosestFire(GetShapeWorldTransform(ammo_rack).pos, 0.25)
			-- if( hit) then
			-- 	DebugPrint("ammo rack on fire")
			-- end
			if(tank.ammo_rack_state[i] and IsShapeBroken(ammo_rack) or 
				(tank.ammo_rack_state[i] and hit) or (DEBUG and InputPressed("y"))) then 

				tank.ammo_rack_state[i] = false
				local tag_value = GetTagValue(ammo_rack,"ammo_rack")
				local explosionChance = math.random()
				if(DEBUG) then 
					DebugWatch("tank engines exist","maybe")
					DebugWatch("tank engines # ",#tank.engines )
				end
				if(#tank.engines>0) then 
					if(DEBUG) then
						DebugWatch("old explosion chance",explosionChance)
					end
					explosionChance = explosionChance - (tank.damaged_engines/#tank.engines )
					if(DEBUG) then
						DebugWatch("new explosion chance",explosionChance)
					end
				end
				-- [ big boom mode ]
					--explosionChance  = 0
			--	DebugPrint("ammo rack 	destroyed!")
				if(tag_value=="" or tonumber(tag_value)>explosionChance) then 
					tank.cooking_off = true
					break_all_breakable_joints()


				--	DebugPrint("ammo rack destroyed! cooking off")
					cook_off_intensity = math.random(1,10)
					if(cook_off_intensity<=2 and min_cook_off<4) then 
						min_cook_off = 4
					end			
					SetValue("cook_off_value", 1, "easein", math.random(min_cook_off,max_cook_off))
		
					if(not IsHandleValid(tank.cook_off_loc)) then 
						tank.cook_off_origin =TransformToLocalTransform(GetVehicleTransform(tank.id), GetShapeWorldTransform(ammo_rack))
						if(HasTag(ammo_rack,"explosive_force") and (GetTagValue(ammo_rack,"explosive_force"))) then
							explosive_force = (GetTagValue(ammo_rack,"explosive_force"))
						end
					end
				end
			end
		end
		if(stable_ammo<=0) then 
			tank.cooking_off = true
			break_all_breakable_joints()
		--	DebugPrint("ammo rack destroyed! cooking off")

			SetValue("cook_off_value", 1, "easein", math.random(min_cook_off,max_cook_off))
			cook_off_intensity = math.random(1,2)

			if(not IsHandleValid(tank.cook_off_loc)) then 
				local i = math.random(1,#tank.ammo_racks)
				tank.cook_off_origin =TransformToLocalTransform(GetVehicleTransform(tank.id), GetShapeLocalTransform(tank.ammo_racks[i]))
				if(HasTag(ammo_rack,"explosive_force") and (GetTagValue(ammo_rack,"explosive_force"))) then
					explosive_force = (GetTagValue(ammo_rack,"explosive_force"))
				end				
			end
		elseif(#tank.ammo_rack_state>1 and (stable_ammo < #tank.ammo_rack_state/2)) then 
			break_all_breakable_joints()
		end
		if(tank.cooking_off) then 

			SetTag(tank.id, "vehicle_disabled")
			if(IsHandleValid(base_vehicle)) then 
				SetTag(tank.base_vehicle, "vehicle_disabled")
			end
		end
	-- else 
	-- 	cook_off()
	end
end



function break_all_breakable_joints()
	for i=1,#breakable_joints do 
		-- DebugPrint("i"..i)
		if(IsHandleValid(breakable_joints[i])) then 
			local tag_value = GetTagValue(breakable_joints[i],"break_joint")
			local break_chance = math.random()
			if(tag_value=="" or tonumber(tag_value)>break_chance) then 		
				Delete(breakable_joints[i])	
				if(DEBUG) then
					DebugWatch("break chance",break_chance)

					DebugWatch("tag value ",tag_value)
				end
			end
		
		end
		-- DebugPrint("gone: "..i)
	end

end

function cook_off()
	local dt = GetTimeStep()
	local transform = TransformToParentTransform(GetVehicleTransform(tank.id),tank.cook_off_origin)
	local pos = transform.pos
	-- for i=1,10 do
	-- 	local holePos = TransformToParentPoint(transform, Vec(0,i/5,0)) 
	-- 	DebugCross(holePos)
	-- 	DebugWatch("holepos",holePos)

	-- end	
	IT_PlayLoop(cook_off_loop, pos, cook_off_sound_vol*cook_off_value)
	if(cook_off_value<1) then 
		EmitFire(cook_off_pulse*5, transform,math.max(0.2,cook_off_value*1.5),1)
		if(cook_off_pulse<=0) then 
			IT_PlaySound(cook_off_sounds[math.random(1,#cook_off_sounds)], pos, cook_off_sound_vol*cook_off_value, false)
			if(cook_off_value<=1) then
				tank_ignition(transform)
				
				for i=1,#tank.burn_off_origins do 
					local ignition_pos = TransformToParentTransform(GetVehicleTransform(tank.id),tank.burn_off_origins[i])
					tank_ignition(ignition_pos)
				end

				for i=1,15 do
					local holePos = TransformToParentPoint(transform, Vec(0,i/5,0))
					local holesize = math.min(hatch_size * (cook_off_value*hole_force),hatch_size) 
					MakeHole(holePos, holesize, holesize,holesize)

				end

			end 
			local cook_off_frequency = math.random(10,10+(60*(1.1-cook_off_value)))/100
			SetValue("cook_off_pulse", 1, "linear", cook_off_frequency)
			local strength = cook_off_value
			local pos =transform.pos
			if strength >= 0.95 and cook_off_intensity>1 then
				ITC_explosionLarge(pos)
			elseif strength >= 0.7 then
				ITC_explosionMedium(pos)
			else
				ITC_explosionSmall(pos)
				
				
			end





			if(tank.hatches_blown<3 and  cook_off_value>0.2) then 
				apply_impulse(transform)
				
				for i=1,#tank.blow_out_origins do 
					if(math.random()>0.5) then 
						apply_impulse(tank.blow_out_origins[i])
					end
				end
				tank.hatches_blown =tank.hatches_blown +1
			end

			



		elseif(cook_off_pulse>=1) then
			cook_off_pulse=0
		end
		
		ITC_flashTick(explosionPos, dt)
		ITC_lightTick(explosionPos, dt)
	elseif(not tank.dead) then
		if( cook_off_intensity>2) then 
			cook_off_blast()
			Explosion(pos, (math.random(5,17)/10)*explosive_force)
			IT_PlaySound(tank_explode_sounds[math.random(1,#tank_explode_sounds)], pos, tank_explode_sound_vol*cook_off_value, false)
			max_burn_off = max_burn_off /2
		end
		-- else
			SetValue("burn_off_value", 0, "easeout", math.random(min_burn_off,max_burn_off))
			tank.burning_off = true
		-- end
		kill_tracks()
		
		SetTag(tank.id, "nodrive")
		if(IsHandleValid(base_vehicle)) then 
			SetTag(tank.base_vehicle, "nodrive")
		end
		
	--	DebugPrint("Did something go boom?")
		tank.dead=true
	end

end


function tank_ignition(transform)
	local hitLocations = {nil,nil,nil}
	for i=1,3 do 
		local queryPos = VecAdd(transform.pos,Vec(math.random()*math.random(-1,1),math.random()*math.random(-1,1),math.random()*math.random(-1,1)))
		for j=1,3 do
			if(hitLocations[j])then 
				QueryRejectShape(hitLocations[j])
			end
		end
		local hit, hitp,hitn,hitshape = QueryClosestPoint(queryPos,1.4)
		if(hit) then
				SpawnFire(hitp)
				hitLocations[i] = hitshape
		else
				SpawnFire(pos)
		end
	end
	spawn_cookoff_debris(transform.pos)
end


