function rnd(mi, ma)
	return math.random(1000)/1000*(ma-mi) + mi
end

function rndVec(t)
	return Vec(rnd(-t, t), rnd(-t, t), rnd(-t, t))
end

explosionPos = Vec()

trails = {}

function ITR_trailsAdd(pos, vel, life, size, damp, gravity)
	t = {}
	t.pos = VecCopy(pos)
	t.vel = VecAdd(Vec(0, vel*0.7, 0 ), rndVec(vel))
	t.size = size
	t.age = 0
	t.damp = damp
	t.gravity = gravity
	t.life = rnd(life*0.5, life*1.5)
	t.nextSpawn = 0
	trails[#trails+1] = t
end

function ITR_trailsUpdate(dt)
	for i=#trails,1,-1 do
		local t = trails[i]
		t.vel[2] = t.vel[2] + t.gravity*dt
		t.vel = VecScale(t.vel, t.damp)
		t.pos = VecAdd(t.pos, VecScale(t.vel, dt))
		t.age = t.age + dt
		local q = 1.0 - t.age / t.life
		if q > 0.1 then
			local r = t.size * q + 0.05
			local spawnRate = 0.8*r/VecLength(t.vel)
			while t.nextSpawn < t.age do
				local w = 0.8-q*0.5
				local w2 = 0.9
				local v = VecScale(t.vel, 0.25)
				IT_ParticleReset()
				IT_ParticleType("smoke")
				IT_ParticleColor(w, w*0.95, w*0.9, w2, w2*0.95, w2*0.9)
				IT_ParticleRadius(r)
				IT_ParticleAlpha(q, 0)
				IT_ParticleDrag(2.0)
				IT_SpawnParticle(t.pos, v, rnd(0.5, 2.0))
				t.nextSpawn = t.nextSpawn + spawnRate
			end
		else
			trails[i] = trails[#trails]
			trails[#trails] = nil
		end
	end
end

smoke = {}
smoke.age = 0
smoke.size = 0
smoke.life = 0
smoke.next = 0
smoke.vel = 0
smoke.gravity = 0
smoke.amount = 0
function ITR_smokeUpdate(pos, dt)
	smoke.age = smoke.age + dt
	if smoke.age < smoke.life then
		local q = 1.0 - smoke.age / smoke.life
		for i=1, smoke.amount*q do
			local w = 0.8-q*0.6
			local w2 = 1.0
			local r = smoke.size*(0.5 + 0.5*q)
			local v = VecAdd(Vec(0, 1*q+q*smoke.vel, 0), rndVec(1*q))
			local p = VecAdd(pos, rndVec(r*0.3))
			IT_ParticleReset()
			IT_ParticleType("smoke")
			IT_ParticleColor(w, w*0.95, w*0.9, w2, w2*0.95, w2*0.9)
			IT_ParticleRadius(0.5*r, r)
			IT_ParticleGravity(rnd(0,smoke.gravity))
			IT_ParticleDrag(1.0)
			IT_ParticleAlpha(q, q, "constant", 0, 0.5)
			IT_SpawnParticle(p, v, rnd(3,5))
		end
	end
end


fire = {}
fire.age = 0
fire.life = 0
fire.size = 0
function ITR_fireUpdate(pos, dt)
	fire.age = fire.age + dt
	if fire.age < fire.life then
		local q = 1.0 - fire.age / fire.life
		for i=1, 16 do
			local v = rndVec(fire.size*10*q)
			v[2] = v[2] * math.random(1,upward_force)
			local p = pos
			local life = rnd(0.2, 0.7)
			life = 0.5 + life*life*life * 1.5
			IT_ParticleReset()
			IT_ParticleColor(1, 0.6, 0.4, 1, 0.3, 0.2)
			IT_ParticleAlpha(1, 0)
			IT_ParticleRadius(fire.size*q, 0.5*fire.size*q)
			IT_ParticleGravity(1, rnd(1, 10))
			IT_ParticleDrag(0.6)
			IT_ParticleEmissive(rnd(2, 5), 0, "easeout")
			IT_ParticleTile(5)
			IT_SpawnParticle(p, v, life)
		end
	end
end


