	light.age = light.age + dt
	if light.age < light.life then
		local q = 1.0 - light.age / light.life
		local l = q * q
		local p = VecAdd(pos, rndVec(0.5*l))
		IT_PointLight(p, 1, 0.4, 0.1, light.intensity*l)
	end
