function ITR_explosionSparks(count, vel, explosionPos)
	for i=1, count do
		local v = VecAdd(Vec(0, vel, 0 ), rndVec(rnd(vel*0.5, vel*1.5)))
		local life = rnd(0, 1)
		life = life*life * 5
		IT_ParticleReset()
		IT_ParticleEmissive(5, 0, "easeout")
		IT_ParticleGravity(-10)
		IT_ParticleRadius(0.03, 0.0, "easein")
		IT_ParticleColor(1, 0.4, 0.3)
		IT_ParticleTile(4)
		IT_SpawnParticle(explosionPos, v, life)
	end
end

function ITR_explosionDebris(count, vel, explosionPos)
	for i=1, count do
		local r = rnd(0, 1)
		life = 0.5 + r*r*r*3
		r = (0.4 + 0.6*r*r*r)
		local v = VecAdd(Vec(0, r*vel*0.5, 0), VecScale(rndVec(1), r*vel))
		local radius = rnd(0.03, 0.05)
		local w = rnd(0.2, 0.5)
		IT_ParticleReset()
		IT_ParticleColor(w, w, w)
		IT_ParticleAlpha(1)
		IT_ParticleGravity(-10)
		IT_ParticleRadius(radius, radius, "constant", 0, 0.2)
		IT_ParticleSticky(0.2)
		IT_ParticleStretch(0.0)
		IT_ParticleTile(6)
		IT_ParticleRotation(rnd(-20, 20), 0.0, "easeout")
		IT_SpawnParticle(explosionPos, v, life)
	end
end

