end


function ITR_explosionMedium(pos)
	explosionPos = pos
	ITC_explosionSparks(30, 3, explosionPos)
	ITC_explosionDebris(50, 7, explosionPos)

	trails = {}
	for i=1, 16 do
		ITC_trailsAdd(pos, 12, 0.4, 0.15, 0.97, -10)
	end

	flash.age = 0
	flash.life = 0.2
	flash.intensity = 500
	
	light.age = 0
	light.life = 1.0
	light.intensity = 30
	
	fire.age = 0
	fire.life = 0.6
	fire.size = 0.5

	smoke.age = 0
	smoke.life = 1.5
	smoke.size = 0.7
	smoke.vel = 1
	smoke.gravity = 2
	smoke.amount = 2
end


function ITR_explosionLarge(pos)
	explosionPos = pos
	ITC_explosionSparks(50, 5, explosionPos)
	ITC_explosionDebris(100, 10, explosionPos)

	trails = {}
	for i=1, 8 do
		ITC_trailsAdd(pos, 12, 0.5, 0.2, 0.97, -10)
	end

	flash.age = 0
	flash.life = 0.4
	flash.intensity = 1000
	
	light.age = 0
	light.life = 1.2
	light.intensity = 50
	
	fire.age = 0
	fire.life = 0.7
	fire.size = 0.8
	
	smoke.age = 0
	smoke.life = 3
	smoke.size = 1.0
	smoke.gravity = -1
	smoke.vel = 8
	smoke.amount = 6
	
	--Sideways fast cloud
	IT_ParticleReset()
	IT_ParticleColor(0.8, 0.75, 0.7)
	IT_ParticleRadius(0.3, 1.0)
	IT_ParticleAlpha(1, 0, "easeout")
	IT_ParticleDrag(0.2)
	for a=0, math.pi*2, 0.05 do
		local x = math.cos(a)*1
		local y = rnd(-0.1, 0.1)
		local z = math.sin(a)*1
		local d = VecNormalize(Vec(x, y, z))
		IT_SpawnParticle(VecAdd(pos, d), VecScale(d, rnd(8,12)), rnd(0.5, 1.5))
	end
end


function client.update(dt) -- (v2) the effects' continuous updates run on every client
	ITC_trailsUpdate(dt)
	ITC_fireUpdate(explosionPos, dt)
	ITC_smokeUpdate(explosionPos, dt)
end



-- (v2) effect functions by name, for client.itFx
ITR_FX = { trailsAdd = ITR_trailsAdd, trailsUpdate = ITR_trailsUpdate, smokeUpdate = ITR_smokeUpdate, fireUpdate = ITR_fireUpdate, flashTick = ITR_flashTick, lightTick = ITR_lightTick, explosionSparks = ITR_explosionSparks, explosionDebris = ITR_explosionDebris, explosionSmall = ITR_explosionSmall, explosionMedium = ITR_explosionMedium, explosionLarge = ITR_explosionLarge, engine_sparks = ITR_engine_sparks, animated_fuel_leak = ITR_animated_fuel_leak, EmitFireFx = ITR_EmitFireFx }
